INSERT INTO `website_policies` (`id`, `privacy_policy`, `terms_conditions`, `refund_policy`, `payment_policy`, `about_us`, `created_at`, `updated_at`) VALUES
(1, '<p style=\"padding: 0px; margin: 0px 0px 1rem; font-size: 14px; line-height: 1.4; color: rgb(77, 81, 84); font-family: Poppins;\"><span style=\"padding: 0px; margin: 0px; font-weight: bolder;\">banggomart.com</span>&nbsp;এ আপনাকে স্বাগতম।&nbsp;<span style=\"padding: 0px; margin: 0px; font-weight: bolder;\">banggomart.com</span>&nbsp;হলো&nbsp;<span style=\"padding: 0px; margin: 0px; font-weight: bolder;\">Webcoder-IT Institute</span>&nbsp;এর একটি অঙ্গপ্রতিষ্ঠান এবং এই ওয়েবসাইটটির মালিক ও পরিচালক&nbsp;<span style=\"padding: 0px; margin: 0px; font-weight: bolder;\">Webcoder-IT Institute</span>&nbsp;নিজেই। আমরা আমাদের ওয়েবসাইট ব্যবহারকারীদের গোপনীয়তা রক্ষায় সদা তৎপর এবং তাই আপনাদের তথ্যের গোপনীয়তা রক্ষায় আমরা একটি গোপনীয়তা নীতিমালায় প্রকাশ করছি যেখানে আমরা কিভাবে আপনাদের গোপনীয়তা রক্ষা করবো তার বিস্তারিত ভাবে বর্ণণা করা হয়েছে। এই নীতিমালায় আমরা কিভাবে আপনার তথ্য সংগ্রহ ও ব্যবহার করি, কিভাবে আমরা আপনার ব্যক্তিগত তথ্যের সুরক্ষা নিশ্চিত করি তারও বিস্তারিত বর্ণনা রয়েছ। আমরা শুধুমাত্র আমাদের ওয়েবসাইট ব্যবহার করে অর্ডার করতে যে তথ্যগুলো প্রয়োজন সেই তথ্যগুলোই সংগ্রহ করে থাকি। বিস্তারিত জানতে অনুগ্রহ করে সময় নিয়ে গোপনীয়তা নীতিমালাটি পড়ুন।</p><p style=\"padding: 0px; margin: 0px 0px 1rem; font-size: 14px; line-height: 1.4; color: rgb(77, 81, 84); font-family: Poppins;\"><span style=\"padding: 0px; margin: 0px; font-weight: bolder;\">ব্যক্তিগত তথ্যঃ</span><br style=\"padding: 0px; margin: 0px;\">আপনি যখন আমাদের ওয়েবসাইটে রেজিস্ট্রেশন করেন তখন আপনার ফোন নাম্বার নেয়া হয়। পরবর্তীতে আপনি যখন অর্ডার দিতে যান তখন আপনার নাম, ফোন নাম্বার, ইমেইল এড্রেস, ঠিকানা এবং অনলাইন পেমেন্টের ক্ষেত্রে আপনার কার্ড/বিকাশ/নগদ সংক্রান্ত তথ্য নেয়া হয়। আপনার যাবতীয় তথ্য আমরা নিরাপদ ও সুরক্ষিত সার্ভারে সংগ্রহ করি এবং SSL সার্টিফিকেট, ম্যালওয়ার স্ক্যান, হ্যাক স্ক্যান ইত্যাদি সিকিউরিটি টুলসের মাধ্যমে সর্বোচ্চ নিরাপত্তা নিশ্চিত করে থাকি।</p><p style=\"padding: 0px; margin: 0px 0px 1rem; font-size: 14px; line-height: 1.4; color: rgb(77, 81, 84); font-family: Poppins;\"><span style=\"padding: 0px; margin: 0px; font-weight: bolder;\">লেনদেন সংক্রান্ত তথ্যঃ</span><br style=\"padding: 0px; margin: 0px;\">অনলাইন লেনদেনের ক্ষেত্রে বিকাশ/নগদ/ডেবিট কিংবা ক্রেডিট কার্ডের ব্যবহার বৃদ্ধির সাথে সাথে প্রতারক চক্রের সংখ্যাও বেড়ে চলেছে আর তাই আপনাদের তথ্যের নিরাপত্তা নিশ্চিত করতে আমরা আমাদের ওয়েবসাইটে ব্যবহার করছি বাংলাদেশের সবচেয়ে সিকিউরড ও ইউজার ফ্রেন্ডলি পেমেন্ট গেটওয়ে SSLCOMMERZ যা আপনার অনলাইন পেমেন্টকে করবে ১০০% নিরাপদ। তাছাড়া আমাদের সাইট থেকে আপনি যখন পেমেন্ট করতে যাবেন তখন আপনাকে আমাদের সাইট থেকে সরাসরি SSLCOMMERZ পেজ এ নিয়ে যাবে পেমেন্ট কমপ্লিট করার জন্যে যা আপনার কার্ডের তথ্যকে রাখবে আরও নিরাপদ। এ ছাড়াও আমাদের রয়েছে নিজস্ব Bkash Payment গেটওয়ে যা দিয়ে আপনি আপনার বিকাশ একাউন্ট থেকে পেমেন্ট করতে পারবেন নিরাপদে।</p><p style=\"padding: 0px; margin: 0px 0px 1rem; font-size: 14px; line-height: 1.4; color: rgb(77, 81, 84); font-family: Poppins;\"><span style=\"padding: 0px; margin: 0px; font-weight: bolder;\">তথ্য সরবরাহঃ</span><br style=\"padding: 0px; margin: 0px;\">আমরা আপনার ব্যক্তিগত তথ্য অন্য কোনো ব্যক্তি বা প্রতিষ্ঠান কে প্রদান করি না। শুধুমাত্র আপনার অর্ডারকৃত পণ্য কুরিয়ার করার ক্ষেত্রে কুরিয়ার সার্ভিস কোম্পানিকে দেয়া হয়। সেইক্ষেত্রে কুরিয়ার সার্ভিস কোম্পানি তাদের ব্যবসায়িক প্রমোশন বা অন্য কাজে এই তথ্য ব্যবহার করলে তার দায়ভার সম্পূর্ণ আমাদের দায়বদ্ধতার বাইরে। তবে দেশের আইন প্রযোগকারী কোন সংস্থা যদি দেশের কাজে তাদের কোন তদন্তের প্রয়োজনে তথ্য চায় সেই ক্ষেত্রে আমরা দিতে বাধ্য থাকবো।</p><p style=\"padding: 0px; margin: 0px 0px 1rem; font-size: 14px; line-height: 1.4; color: rgb(77, 81, 84); font-family: Poppins;\"><span style=\"padding: 0px; margin: 0px; font-weight: bolder;\">কুকিসঃ</span><br style=\"padding: 0px; margin: 0px;\">কুকিস হচ্ছে ছোট একটি ফাইল যা ব্রাউজারের মাধ্যমে আপনার সম্মতি নেয়ার মাধ্যমে আপনার হার্ড ড্রাইভে সংগ্রহ করি। আমরা কুকিস সংগ্রহ করার মাধ্যমে আমরা আপনি কোন ব্রাউজারটি ব্যবহার করছেন তা চিনতে পারি, আপনার পরিচয় বুঝতে পারি যাতে করে ভবিষ্যতে আপনাকে আরো ভালো ওয়েবসাইট এক্সপেরিয়েন্স দিতে পারি। আমাদের ওয়েবসাইটের বাইরেও অন্য কোনো তৃতীয় পক্ষের কুকিস আমাদের সাইট ব্যবহারের সময় আপনি পেতে পারেন (যেমন আপনি যদি আমাদের ওয়েবসাইট থেকে অন্য কারো তৈরি করা ওয়েব পেইজে ব্রাউজ করেন, তার কুকিস চলে আসতে পারে)। আমরা এই ওয়েবসাইটের ব্যবহার পর্যবেক্ষণ করার জন্য গুগল অ্যানালিটিক্স ব্যবহার করে থাকি। গুগল অ্যানালিটিক্স আপনার কম্পিউটারে কুকিস সংরক্ষণ করে বিভিন্ন পরিসংখ্যান ও অন্যান্য তথ্য আমাদেরকে প্রদান করে। আমাদের ওয়েবসাইট সংক্রান্ত এসব তথ্য ওয়েবসাইটের ব্যবহার সম্পর্কিত রিপোর্ট তৈরিতে সহায়তা করে।</p><p style=\"padding: 0px; margin: 0px 0px 1rem; font-size: 14px; line-height: 1.4; color: rgb(77, 81, 84); font-family: Poppins;\"><span style=\"padding: 0px; margin: 0px; font-weight: bolder;\">গোপনীয়তা নীতিমালা পরিবর্তনঃ</span><br style=\"padding: 0px; margin: 0px;\">এই গোপনীয়তা নীতিমালাটি&nbsp;<span style=\"padding: 0px; margin: 0px; font-weight: bolder;\">banggomart.com</span>&nbsp;যেকোন সময়ে পরিবর্তন করার অধিকার রাখে। আমাদের গোপনীয়তা নীতিমালায় যদি কোন পরিবর্তন আনা হয়, সেই ক্ষেত্রে পরিবর্তিত গোপনীয়তা নীতিমালাটি আমরা এখানে রাখবো।</p><p style=\"padding: 0px; margin: 0px 0px 1rem; font-size: 14px; line-height: 1.4; color: rgb(77, 81, 84); font-family: Poppins;\"><span style=\"padding: 0px; margin: 0px; font-weight: bolder;\">আপনার সম্মতিঃ</span><br style=\"padding: 0px; margin: 0px;\">আমাদের ওয়েবসাইট&nbsp;<span style=\"padding: 0px; margin: 0px; font-weight: bolder;\">(banggomart.com)</span>&nbsp;ব্যবহার করার মাধ্যমে আপনি এই গোপনীয়তা নীতিমালায় সম্মতি প্রকাশ করছেন। আমাদের গোপনীয়তা নীতিমালা নিয়ে আপনার যদি কোন প্রশ্ন বা জিজ্ঞাসা থেকে থাকে তাহলে আমাদের সাথে যোগাযোগ করার অনুরোধ করা হলো। আমাদের সাথে যোগাযোগের ইমেইলঃ&nbsp;<span style=\"padding: 0px; margin: 0px; font-weight: bolder;\">banggomartbd@gmail.com</span></p>', 'Test terms-conditions up', 'Test refund policy up', 'Test payment policy up', 'Test About us up', NULL, '2026-05-10 09:52:45');

